static field_ip_config cfg;static int ready,pinned;static uint64_t suspended_until;static volatile int online,connecting,revision;static int socket_fd=-1;
static QueueHandle_t inbox;static TaskHandle_t udp_handle;static uint64_t next_connect,connect_deadline,next_register,lease_until;static uint32_t session,entry_boot,retired_sessions[4];static unsigned retired_session_cursor;static mid_id entry;
typedef struct {uint64_t cursor,at;unsigned attempts;char data[896];} field_ip_event;
static field_ip_event retained[16];static unsigned event_head,event_count;static uint64_t event_cursor;static uint32_t event_overflow,rx_drops,send_fail,channel_drift,channel_restore_failures;
static void address(mid_id id,char*s){snprintf(s,18,"%02x:%02x:%02x:%02x:%02x:%02x",id.mac[0],id.mac[1],id.mac[2],id.mac[3],id.mac[4],id.mac[5]);}
static void handler(void*a,esp_event_base_t base,int32_t id,void*data){(void)a;(void)data;if(base==IP_EVENT&&id==IP_EVENT_STA_GOT_IP){online=1;connecting=0;}else if(base==WIFI_EVENT&&(id==WIFI_EVENT_STA_DISCONNECTED||id==WIFI_EVENT_STA_STOP)){online=connecting=0;}}
static void udp_task(void*unused){(void)unused;int own_rev=-1;char line[1026];for(;;){if(own_rev!=revision||socket_fd<0){if(socket_fd>=0)close(socket_fd);socket_fd=socket(AF_INET,SOCK_DGRAM,IPPROTO_UDP);own_rev=revision;if(socket_fd>=0){struct sockaddr_in addr={.sin_family=AF_INET,.sin_port=htons(cfg.listen_port?cfg.listen_port:8792),.sin_addr.s_addr=htonl(INADDR_ANY)};if(bind(socket_fd,(struct sockaddr*)&addr,sizeof(addr))<0){close(socket_fd);socket_fd=-1;}else fcntl(socket_fd,F_SETFL,O_NONBLOCK);}}if(socket_fd<0){vTaskDelay(pdMS_TO_TICKS(1000));continue;}struct sockaddr_in from;socklen_t size=sizeof(from);int len=recvfrom(socket_fd,line,1025,0,(struct sockaddr*)&from,&size);if(len>1024){rx_drops++;continue;}if(len>0&&cfg.enabled&&from.sin_addr.s_addr==inet_addr(cfg.pc_ip)){if(memchr(line,0,(size_t)len)){rx_drops++;continue;}line[len]=0;if(xQueueSend(inbox,line,0)!=pdTRUE)rx_drops++;}vTaskDelay(pdMS_TO_TICKS(20));}}
esp_err_t field_ip_load(void){memset(&cfg,0,sizeof(cfg));cfg.listen_port=8792;cfg.pc_port=8793;nvs_handle_t h;esp_err_t r=nvs_open("field_ip",NVS_READONLY,&h);if(r==ESP_ERR_NVS_NOT_FOUND)return ESP_OK;if(r!=ESP_OK)return r;size_t n=sizeof(cfg);r=nvs_get_blob(h,"cfg",&cfg,&n);nvs_close(h);if(r==ESP_ERR_NVS_NOT_FOUND){memset(&cfg,0,sizeof(cfg));return ESP_OK;}if(r!=ESP_OK||n!=sizeof(cfg)||cfg.magic!=0x32495046||!memchr(cfg.ssid,0,33)||!memchr(cfg.password,0,65)||!memchr(cfg.pc_ip,0,16)){memset(&cfg,0,sizeof(cfg));return ESP_ERR_INVALID_ARG;}return ESP_OK;}
esp_err_t field_ip_store(const field_ip_config*c){if(c->magic!=0x32495046||!c->pc_id||c->channel<1||c->channel>13||!mid_unicast((mid_id){{c->bssid[0],c->bssid[1],c->bssid[2],c->bssid[3],c->bssid[4],c->bssid[5]}})||!memchr(c->ssid,0,33)||!memchr(c->password,0,65)||!memchr(c->pc_ip,0,16)||!strlen(c->ssid)||inet_addr(c->pc_ip)==INADDR_NONE||c->listen_port<1024||c->pc_port<1024)return ESP_ERR_INVALID_ARG;nvs_handle_t h;esp_err_t r=nvs_open("field_ip",NVS_READWRITE,&h);if(r!=ESP_OK)return r;r=nvs_set_blob(h,"cfg",c,sizeof(*c));if(r==ESP_OK)r=nvs_commit(h);nvs_close(h);if(r==ESP_OK){cfg=*c;revision++;lease_until=0;pinned=0;}return r;}
esp_err_t field_ip_clear(void){nvs_handle_t h;esp_err_t r=nvs_open("field_ip",NVS_READWRITE,&h);if(r!=ESP_OK)return r;r=nvs_erase_key(h,"cfg");if(r==ESP_ERR_NVS_NOT_FOUND)r=ESP_OK;if(r==ESP_OK)r=nvs_commit(h);nvs_close(h);if(r==ESP_OK){memset(&cfg,0,sizeof(cfg));revision++;lease_until=0;pinned=0;}return r;}
void field_ip_netif(void){esp_log_level_set("wifi",ESP_LOG_NONE);esp_log_level_set("wifi_init",ESP_LOG_NONE);esp_log_level_set("wpa",ESP_LOG_NONE);if(ready)return;esp_netif_create_default_wifi_sta();esp_event_handler_register(IP_EVENT,IP_EVENT_STA_GOT_IP,handler,NULL);esp_event_handler_register(WIFI_EVENT,WIFI_EVENT_STA_DISCONNECTED,handler,NULL);inbox=xQueueCreate(8,1025);if(inbox&&xTaskCreate(udp_task,"field_udp",4096,NULL,3,&udp_handle)==pdPASS)ready=1;}
int field_ip_pin(uint8_t channel){pinned=0;if(!cfg.enabled)return 1;if(channel!=cfg.channel)return 0;wifi_country_t country={.cc="CN",.schan=channel,.nchan=1,.max_tx_power=20,.policy=WIFI_COUNTRY_POLICY_MANUAL};wifi_country_t check;if(esp_wifi_set_country(&country)!=ESP_OK||esp_wifi_get_country(&check)!=ESP_OK||check.schan!=channel||check.nchan!=1||check.policy!=WIFI_COUNTRY_POLICY_MANUAL)return 0;wifi_config_t config={0};memcpy(config.sta.ssid,cfg.ssid,strlen(cfg.ssid));memcpy(config.sta.password,cfg.password,strlen(cfg.password));config.sta.channel=channel;config.sta.bssid_set=true;memcpy(config.sta.bssid,cfg.bssid,6);config.sta.scan_method=WIFI_FAST_SCAN;config.sta.failure_retry_cnt=0;config.sta.threshold.authmode=strlen(cfg.password)?WIFI_AUTH_WPA2_PSK:WIFI_AUTH_OPEN;if(esp_wifi_set_config(WIFI_IF_STA,&config)!=ESP_OK)return 0;pinned=1;next_connect=0;return 1;}
void field_ip_base(cJSON*j,const char*event){char mac[18];address(entry,mac);cJSON_AddStringToObject(j,"schema","field.ip.v2");cJSON_AddStringToObject(j,"event",event);cJSON_AddStringToObject(j,"entry_id",mac);cJSON_AddNumberToObject(j,"entry_boot",entry_boot);cJSON_AddNumberToObject(j,"pc_id",cfg.pc_id);cJSON_AddNumberToObject(j,"pc_session",session);cJSON_AddNumberToObject(j,"entry_uptime_ms",(double)((uint64_t)esp_timer_get_time()/1000));}
static int send_line(const char*text){if(socket_fd<0||!online){send_fail++;return 0;}struct sockaddr_in to={.sin_family=AF_INET,.sin_port=htons(cfg.pc_port),.sin_addr.s_addr=inet_addr(cfg.pc_ip)};if(sendto(socket_fd,text,strlen(text),MSG_DONTWAIT,(struct sockaddr*)&to,sizeof(to))<0){send_fail++;return 0;}return 1;}
void field_ip_emit(cJSON*j,int keep){
 uint64_t now=(uint64_t)esp_timer_get_time()/1000;if(keep){cJSON_AddNumberToObject(j,"event_cursor",(double)++event_cursor);cJSON_AddNumberToObject(j,"event_created_ms",(double)now);cJSON_AddNumberToObject(j,"entry_event_age_ms",0);}
 char*text=cJSON_PrintUnformatted(j);if(!text){cJSON_Delete(j);return;}if(strlen(text)>1024){event_overflow++;cJSON_free(text);cJSON_Delete(j);cJSON*small=cJSON_CreateObject();field_ip_base(small,"rejected");cJSON_AddStringToObject(small,"error","response_limit1024");field_ip_emit(small,0);return;}int submitted=send_line(text);cJSON_free(text);
 /* Full history must not suppress live telemetry or evict business receipts. */
 if(keep&&event_count==16&&cJSON_IsString(cJSON_GetObjectItemCaseSensitive(j,"event"))&&!strcmp(cJSON_GetObjectItemCaseSensitive(j,"event")->valuestring,"report")){event_overflow++;cJSON_Delete(j);return;}
 if(keep){cJSON_AddBoolToObject(j,"last_ip_submit_ok",submitted);cJSON_AddNumberToObject(j,"ip_attempts",1);text=cJSON_PrintUnformatted(j);if(text){if(strlen(text)>=sizeof(retained[0].data))event_overflow++;else{if(event_count==16){event_head=(event_head+1)%16;event_count--;event_overflow++;}field_ip_event*e=&retained[(event_head+event_count++)%16];e->cursor=event_cursor;e->at=now;e->attempts=1;snprintf(e->data,sizeof(e->data),"%s",text);}cJSON_free(text);}}cJSON_Delete(j);
}
void field_ip_poll(uint64_t after){for(unsigned i=0;i<event_count;i++){field_ip_event*e=&retained[(event_head+i)%16];if(e->cursor>after){cJSON*j=cJSON_Parse(e->data);if(j){uint64_t now=(uint64_t)esp_timer_get_time()/1000;cJSON_ReplaceItemInObject(j,"entry_event_age_ms",cJSON_CreateNumber((double)(now-e->at)));cJSON_ReplaceItemInObject(j,"entry_uptime_ms",cJSON_CreateNumber((double)now));char*line=cJSON_PrintUnformatted(j);if(line){int sent=send_line(line);cJSON_free(line);e->attempts++;cJSON_ReplaceItemInObject(j,"last_ip_submit_ok",cJSON_CreateBool(sent));cJSON_ReplaceItemInObject(j,"ip_attempts",cJSON_CreateNumber(e->attempts));line=cJSON_PrintUnformatted(j);if(line){if(strlen(line)<sizeof(e->data))snprintf(e->data,sizeof(e->data),"%s",line);cJSON_free(line);}}cJSON_Delete(j);}return;}}cJSON*j=cJSON_CreateObject();field_ip_base(j,"idle");cJSON_AddNumberToObject(j,"latest_cursor",(double)event_cursor);field_ip_emit(j,0);}
void field_ip_export(cJSON*j,uint64_t after){cJSON*a=cJSON_AddArrayToObject(j,"ip_events");unsigned count=0;for(unsigned i=0;i<event_count&&count<4;i++){field_ip_event*e=&retained[(event_head+i)%16];if(e->cursor>after){cJSON*x=cJSON_Parse(e->data);if(x){cJSON_ReplaceItemInObject(x,"entry_event_age_ms",cJSON_CreateNumber((double)((uint64_t)esp_timer_get_time()/1000-e->at)));cJSON_AddItemToArray(a,x);count++;}}}cJSON_AddNumberToObject(j,"latest_cursor",(double)event_cursor);cJSON_AddNumberToObject(j,"oldest_cursor",event_count?(double)retained[event_head].cursor:0);cJSON_AddNumberToObject(j,"event_overflow",event_overflow);}
void field_ip_tick(uint64_t now,int active,uint8_t channel,mid_id self,uint32_t boot){entry=self;entry_boot=boot;if(suspended_until){if(now<suspended_until){lease_until=0;online=connecting=0;if(active&&cfg.enabled){uint8_t current;wifi_second_chan_t second;if(esp_wifi_get_channel(&current,&second)==ESP_OK&&current!=channel){channel_drift++;if(esp_wifi_set_channel(channel,WIFI_SECOND_CHAN_NONE)!=ESP_OK)channel_restore_failures++;}}return;}suspended_until=0;next_connect=0;}if(!active||!cfg.enabled){lease_until=0;online=connecting=0;return;}if(!online)lease_until=0;if(online){uint8_t current;wifi_second_chan_t second;if(esp_wifi_get_channel(&current,&second)!=ESP_OK||current!=channel){channel_drift++;esp_wifi_disconnect();esp_wifi_set_channel(channel,WIFI_SECOND_CHAN_NONE);online=connecting=0;lease_until=0;next_connect=now+60000;}else if(now>=next_register){next_register=now+3000;cJSON*j=cJSON_CreateObject();field_ip_base(j,"register");cJSON_AddNumberToObject(j,"channel",channel);field_ip_status(j,now);field_ip_emit(j,0);}return;}if(connecting){if(now>=connect_deadline){esp_wifi_disconnect();esp_wifi_set_channel(channel,WIFI_SECOND_CHAN_NONE);connecting=0;next_connect=now+60000;}return;}if(pinned&&now>=next_connect){next_connect=now+60000;connect_deadline=now+5000;if(esp_wifi_connect()==ESP_OK)connecting=1;}}
int field_ip_read(char*out,size_t cap){char text[1025];if(cap<1025||!inbox||xQueueReceive(inbox,text,0)!=pdTRUE)return 0;memcpy(out,text,1025);return 1;}
int field_ip_live(uint64_t now){return online&&now<lease_until;}
uint32_t field_ip_pc_id(void){return cfg.pc_id;}uint32_t field_ip_session(void){return session;}uint64_t field_ip_until(void){return online?lease_until:0;}
int field_ip_lease(uint32_t id,uint32_t pc_session,uint32_t target_boot,uint32_t ms,uint32_t own_boot,uint64_t now){if(!online||id!=cfg.pc_id||!pc_session||target_boot!=own_boot||ms<1000||ms>10000)return -1;if(session&&session!=pc_session){for(unsigned i=0;i<4;i++)if(retired_sessions[i]==pc_session)return -1;retired_sessions[retired_session_cursor++%4]=session;}session=pc_session;lease_until=now+ms;return 0;}
void field_ip_status(cJSON*j,uint64_t now){cJSON_AddNumberToObject(j,"ip_status_free_heap_bytes",esp_get_free_heap_size());cJSON_AddNumberToObject(j,"ip_status_minimum_free_heap_bytes",esp_get_minimum_free_heap_size());cJSON_AddNumberToObject(j,"caller_stack_min_free_bytes",(double)uxTaskGetStackHighWaterMark(NULL)*sizeof(StackType_t));cJSON_AddBoolToObject(j,"ip_enabled",cfg.enabled);cJSON_AddBoolToObject(j,"ip_connected",online);cJSON_AddNumberToObject(j,"ip_suspended_until_ms",(double)suspended_until);cJSON_AddBoolToObject(j,"channel_pinned",pinned);cJSON_AddBoolToObject(j,"service_live",field_ip_live(now));cJSON_AddNumberToObject(j,"lease_remaining_ms",field_ip_live(now)?(double)(lease_until-now):0);cJSON_AddNumberToObject(j,"max_payload_bytes",128);cJSON_AddNumberToObject(j,"latest_cursor",(double)event_cursor);cJSON_AddNumberToObject(j,"oldest_cursor",event_count?(double)retained[event_head].cursor:0);cJSON_AddNumberToObject(j,"event_overflow",event_overflow);cJSON_AddNumberToObject(j,"udp_rx_drops",rx_drops);cJSON_AddNumberToObject(j,"udp_send_fail",send_fail);cJSON_AddNumberToObject(j,"channel_drift",channel_drift);cJSON_AddNumberToObject(j,"channel_restore_failures",channel_restore_failures);if(udp_handle)cJSON_AddNumberToObject(j,"udp_stack_min_free_bytes",(double)uxTaskGetStackHighWaterMark(udp_handle)*sizeof(StackType_t));}

void field_ip_unpin(void){lease_until=0;online=connecting=0;if(pinned){esp_wifi_disconnect();wifi_country_t country={.cc="01",.schan=1,.nchan=11,.max_tx_power=20,.policy=WIFI_COUNTRY_POLICY_AUTO};if(esp_wifi_set_country(&country)!=ESP_OK)channel_restore_failures++;wifi_config_t blank={0};esp_wifi_set_config(WIFI_IF_STA,&blank);pinned=0;}}

void field_ip_suspend(uint64_t until){suspended_until=until;lease_until=0;online=connecting=0;esp_wifi_disconnect();if(cfg.channel&&esp_wifi_set_channel(cfg.channel,WIFI_SECOND_CHAN_NONE)!=ESP_OK)channel_restore_failures++;}
